# Definition und Förderverpflichtungen der Kategorie „Agroforststreifen" (AFS)
# (Informationsblatt 1C Kap. 4.1, 5.2, 6; SRL Punkt 2.1C Definitionen/Förderverpflichtungen).
package oepul.o6_1c

negative_list_names := {lower(n.scientific_name) | some n in data.o6_1c.afs_negative_list}

# Gattungseinträge (z. B. Elaeagnus) erfassen alle Arten dieser Gattung.
negative_list_genera := {lower(n.scientific_name) | some n in data.o6_1c.afs_negative_list; n.taxon_rank == "genus"}

on_negative_list(scientific_name) if lower(scientific_name) in negative_list_names

on_negative_list(scientific_name) if {
	genus := split(lower(scientific_name), " ")[0]
	genus in negative_list_genera
}

trees_per_100_m(s) := (s.tree_count * 100) / s.length_m if s.length_m > 0

negative_species_present(s) := {sp.scientific_name |
	some sp in object.get(s, "species", [])
	on_negative_list(sp.scientific_name)
	object.get(sp, "count", 1) > 0
}

# O61C-DEF-AFS-001..008: geometrische und inhaltliche Mindestkriterien der Definition.
afs_defect(s, "O61C-DEF-AFS-001") if object.get(s, "adjacent_to_arable", false) != true

afs_defect(s, "O61C-DEF-AFS-002") if object.get(s, "establishment_year", 0) < params.afs_min_establishment_year

afs_defect(s, "O61C-DEF-AFS-003") if object.get(s, "average_width_m", 0) < params.afs_min_average_width_m

afs_defect(s, "O61C-DEF-AFS-003") if object.get(s, "average_width_m", 0) > params.afs_max_average_width_m

afs_defect(s, "O61C-DEF-AFS-004") if not trees_per_100_m(s)

afs_defect(s, "O61C-DEF-AFS-004") if trees_per_100_m(s) < params.afs_min_trees_per_100_m

afs_defect(s, "O61C-DEF-AFS-004") if trees_per_100_m(s) > params.afs_max_trees_per_100_m

afs_defect(s, "O61C-DEF-AFS-005") if object.get(s, "max_tree_spacing_m", 0) > params.afs_max_tree_spacing_m

afs_defect(s, "O61C-DEF-AFS-006") if object.get(s, "is_special_crop_gspav_25_4", false) == true

afs_defect(s, "O61C-DEF-AFS-007") if count(negative_species_present(s)) > 0

afs_defect(s, "O61C-DEF-AFS-008") if {
	object.get(s, "long_side_adjacent_to_forest_or_area_landscape_element", false) == true
}

afs_defect_ids := [
	"O61C-DEF-AFS-001", "O61C-DEF-AFS-002", "O61C-DEF-AFS-003", "O61C-DEF-AFS-004",
	"O61C-DEF-AFS-005", "O61C-DEF-AFS-006", "O61C-DEF-AFS-007", "O61C-DEF-AFS-008",
]

afs_definition_defects(s) := {id | some id in afs_defect_ids; afs_defect(s, id)}

afs_meets_definition(s) if count(afs_definition_defects(s)) == 0

afs_violations contains v if {
	some s in agroforestry_strips
	some rid in afs_definition_defects(s)
	v := {"rule_id": rid, "scope": s.strip_id, "message": "Agroforststreifen erfüllt die Definition gemäß Informationsblatt Kap. 4.1 nicht"}
}

afs_violations contains v if {
	some s in agroforestry_strips
	object.get(s, "schlagnutzungsart", null) != params.afs_schlagnutzungsart
	v := {"rule_id": "O61C-APPL-005", "scope": s.strip_id, "message": "Agroforststreifen nicht mit Schlagnutzungsart „LSE Agroforststreifen\" beantragt"}
}

# O61C-AFS-001: Neuanlage bis spätestens 15. Mai des Antragsjahres.
afs_violations contains v if {
	some s in agroforestry_strips
	object.get(s, "establishment_year", 0) == year
	d := object.get(s, "planting_date", null)
	d != null
	d > date_in_year(params.afs_new_planting_deadline_month_day)
	v := {"rule_id": "O61C-AFS-001", "scope": s.strip_id, "message": sprintf("Neuanlage am %s nach dem 15. Mai", [d])}
}

# O61C-AFS-002: Entnahme von Gehölzen nur bei weiterer Einhaltung der Mindestkriterien oder Nachpflanzung bis 15. Mai.
afs_violations contains v if {
	some s in agroforestry_strips
	object.get(s, "trees_removed", false) == true
	d := object.get(s, "replanting_date", null)
	d != null
	d > date_in_year(params.afs_replanting_deadline_month_day)
	v := {"rule_id": "O61C-AFS-002", "scope": s.strip_id, "message": sprintf("Nachpflanzung am %s nach dem 15. Mai", [d])}
}

afs_violations contains v if {
	some s in agroforestry_strips
	object.get(s, "trees_removed", false) == true
	object.get(s, "replanting_date", null) == null
	not afs_meets_definition(s)
	v := {"rule_id": "O61C-AFS-002", "scope": s.strip_id, "message": "Gehölzentnahme ohne Einhaltung der Mindestkriterien und ohne Nachpflanzung"}
}

# O61C-AFS-003: erforderliche Pflegemaßnahmen (Pflanzpfahl, Verbissschutz, bedarfsgerechte Pflegeschnitte).
required_care_measures := ["stake_stabilization", "browsing_protection", "pruning_as_needed"]

afs_violations contains v if {
	some s in agroforestry_strips
	some c in required_care_measures
	object.get(s, ["care", c], false) != true
	v := {"rule_id": "O61C-AFS-003", "scope": s.strip_id, "message": sprintf("Pflegemaßnahme %s nicht erfüllt", [c])}
}

# O61C-AFS-004: krautiger Bereich dauerhaft begrünt.
afs_violations contains v if {
	some s in agroforestry_strips
	object.get(s, "herbaceous_permanently_green", false) != true
	v := {"rule_id": "O61C-AFS-004", "scope": s.strip_id, "message": "Krautiger Bereich nicht dauerhaft begrünt"}
}

# O61C-AFS-005: keine Nutzung (Mahd mit Abtransport oder Weide) des krautigen Bereichs; Pflegemahd/Häckseln erlaubt.
permitted_herbaceous_treatments := {"none", "maintenance_mowing", "mulching"}

afs_violations contains v if {
	some s in agroforestry_strips
	u := object.get(s, "herbaceous_use", "none")
	not u in permitted_herbaceous_treatments
	v := {"rule_id": "O61C-AFS-005", "scope": s.strip_id, "message": sprintf("Unzulässige Nutzung des krautigen Bereichs: %v", [u])}
}

# O61C-AFS-006: Dünge- und Pflanzenschutzmittelverbot auf der gesamten Fläche; nur bio-zugelassener Verbissschutz.
afs_violations contains v if {
	some s in agroforestry_strips
	object.get(s, "fertilizer_used", false) == true
	v := {"rule_id": "O61C-AFS-006", "scope": s.strip_id, "message": "Düngung auf Agroforststreifen verboten"}
}

afs_violations contains v if {
	some s in agroforestry_strips
	object.get(s, "psm_used", false) == true
	v := {"rule_id": "O61C-AFS-006", "scope": s.strip_id, "message": "Pflanzenschutzmittel auf Agroforststreifen verboten"}
}

afs_violations contains v if {
	some s in agroforestry_strips
	object.get(s, "browsing_protection_agent_used", false) == true
	object.get(s, "browsing_protection_agent_bio_approved", false) != true
	v := {"rule_id": "O61C-AFS-006", "scope": s.strip_id, "message": "Verbissschutzmittel nicht gemäß Verordnung (EU) 2018/848 zugelassen"}
}

afs_violations contains v if {
	some s in agroforestry_strips
	some other in object.get(parcel_status(s), "other_measure_premium_codes", [])
	not combinable_on_single_area(params.measure_code, other)
	v := {"rule_id": "O61C-COMB-002", "scope": s.strip_id, "message": sprintf("Agroforststreifen laut Anhang L nicht mit Maßnahme %v auf der Einzelfläche kombinierbar", [other])}
}

# O61C-APPL-006: Bei Teilnahme an der Kategorie müssen alle beantragten Agroforststreifen die Verpflichtungen erfüllen.
default afs_all_strips_compliant := false

afs_all_strips_compliant if {
	count(agroforestry_strips) > 0
	count({v | some v in afs_violations}) == 0
}

# O61C-APPL-007: dem Feldstück zugeordnete Agroforststreifen werden bei UBB/BIO auf die 0,15 ha
# Biodiversitätsflächen auf Ackerfeldstücken > 5 ha angerechnet (nicht auf die 7 %-Grenze).
default ubb_or_bio_participant := false

ubb_or_bio_participant if participates("1A")

ubb_or_bio_participant if participates("1B")

afs_credit_15a_by_feldstueck[fid] := credited if {
	ubb_or_bio_participant
	arable_area_ha >= params.ubb_bio_feldstueck_rule_min_arable_area_ha
	some f in feldstuecke
	fid := f.feldstueck_id
	f.arable_area_ha > params.ubb_bio_feldstueck_threshold_ha
	credited := sum([object.get(s, "area_ha", 0) |
		some s in agroforestry_strips
		object.get(s, "assigned_feldstueck_id", null) == fid
	])
}

afs_counts_toward_7_percent := false

# Förderverpflichtungen der Kategorie „Nichtproduktive Ackerflächen" (NPA)
# (Informationsblatt 1C Kap. 5.1, 6, 7; SRL Punkt 2.1C Förderverpflichtungen).
package oepul.o6_1c

removal_methods := data.o6_1c.npa_removal_methods

npa_establishment_options := {o |
	some c in data.o6_1c.measure_categories
	c.category == "npa"
	some o in c.establishment_options
}

# Schläge mit NPA-Angaben (Objekt `npa`) oder NPA-Code gelten als NPA-Schläge.
npa_parcels contains p if {
	some p in parcels
	object.get(p, "npa", null) != null
}

npa_parcels contains p if {
	some p in parcels
	params.npa_code in parcel_codes(p)
}

npa(p) := object.get(p, "npa", {})

npa_first_year(p) if object.get(npa(p), "first_npa_declaration_year", year) == year

npa_events(p) := object.get(npa(p), "maintenance_events", [])

# O61C-NPA-011: Reinigungsschnitt nur im ersten Antragsjahr und nur auf Flächen mit Neuansaat
# (auch bei Umbruch und Neueinsaat einer bestehenden Grünbrache).
cleaning_cut_permitted(p) if {
	npa_first_year(p)
	object.get(npa(p), "establishment_type", null) == "new_sowing"
}

cleaning_cut_permitted(p) if {
	npa_first_year(p)
	object.get(npa(p), "resown_after_breaking_existing_fallow", false) == true
}

valid_cleaning_cut(p, e) if {
	e.type == "cleaning_cut"
	cleaning_cut_permitted(p)
}

# Pflegeschnitte, die zur Maximalanzahl und zur 50 %-Grenze zählen (gültige Reinigungsschnitte ausgenommen).
counted_cuts(p) := [e |
	some e in npa_events(p)
	startswith(e.date, sprintf("%d-", [year]))
	not valid_cleaning_cut(p, e)
]

all_cuts_in_year(p) := [e |
	some e in npa_events(p)
	startswith(e.date, sprintf("%d-", [year]))
]

early_counted_cut(p) if {
	some e in counted_cuts(p)
	e.date < date_in_year(params.npa_late_cut_earliest_month_day)
}

npa_total_area_ha := sum_area(npa_parcels)

npa_early_cut_area_ha := sum([object.get(p, "area_ha", 0) | some p in npa_parcels; early_counted_cut(p)])

# O61C-NPA-012: höchstens 50 % der NPA-Fläche dürfen vor dem 1. August gemäht/gehäckselt werden.
default npa_early_cut_share_exceeded := false

npa_early_cut_share_exceeded if {
	npa_total_area_ha > 0
	npa_early_cut_area_ha > params.npa_late_cut_share * npa_total_area_ha
}

npa_breaking_earliest(p) := date_in_year(params.npa_breaking_earliest_after_winter_or_catch_crop_month_day) if {
	object.get(npa(p), "follow_up_crop", "none") in {"winter_crop", "catch_crop"}
} else := date_in_year(params.npa_breaking_earliest_month_day)

npa_fertilized(p) if object.get(npa(p), "any_fertilization", false) == true

npa_fertilized(p) if object.get(p, ["operations", "fertilizer", "mineral_n_kg_per_ha"], 0) > 0

npa_fertilized(p) if object.get(p, ["operations", "fertilizer", "organic_n_kg_per_ha"], 0) > 0

npa_psm_violation(p) if {
	object.get(p, ["operations", "psm_used"], false) == true
	object.get(npa(p), "psm_only_bio_active_substances", false) != true
}

allowed_removal_method_codes := {m.method | some m in removal_methods.allowed_methods}

npa_violations contains v if {
	some p in npa_parcels
	object.get(p, "land_use", null) != "arable"
	v := {"rule_id": "O61C-NPA-001", "scope": p.parcel_id, "message": "NPA muss eine Ackerfläche sein"}
}

npa_violations contains v if {
	some p in npa_parcels
	not params.npa_code in parcel_codes(p)
	v := {"rule_id": "O61C-APPL-004", "scope": p.parcel_id, "message": "NPA-Schlag ist nicht mit dem Code NPA gekennzeichnet"}
}

npa_violations contains v if {
	some p in npa_parcels
	object.get(p, "schlagnutzungsart", null) != params.npa_schlagnutzungsart
	v := {"rule_id": "O61C-APPL-004", "scope": p.parcel_id, "message": "NPA-Schlag ist nicht mit der Schlagnutzungsart Grünbrache beantragt"}
}

npa_violations contains v if {
	some p in npa_parcels
	not object.get(npa(p), "establishment_type", null) in npa_establishment_options
	v := {"rule_id": "O61C-NPA-002", "scope": p.parcel_id, "message": "Neuansaat, Selbstbegrünung oder Belassen einer bestehenden Grünbrache/dauerhaft begrünten Ackerfläche erforderlich"}
}

npa_violations contains v if {
	some p in npa_parcels
	object.get(npa(p), "establishment_type", null) == "new_sowing"
	npa_first_year(p)
	d := object.get(npa(p), "sowing_date", null)
	d != null
	d > date_in_year(params.npa_new_sowing_deadline_month_day)
	v := {"rule_id": "O61C-NPA-003", "scope": p.parcel_id, "message": sprintf("Neuansaat am %s nach dem 15. Mai", [d])}
}

npa_violations contains v if {
	some p in npa_parcels
	object.get(npa(p), "establishment_type", null) == "new_sowing"
	npa_first_year(p)
	object.get(npa(p), "sowing_date", null) == null
	v := {"rule_id": "O61C-NPA-003", "scope": p.parcel_id, "message": "Neuansaat ohne Ansaatdatum"}
}

npa_violations contains v if {
	some p in npa_parcels
	d := object.get(npa(p), "breaking_date", null)
	d != null
	startswith(d, sprintf("%d-", [year]))
	d < npa_breaking_earliest(p)
	v := {"rule_id": "O61C-NPA-004", "scope": p.parcel_id, "message": sprintf("Umbruch am %s vor dem frühestmöglichen Termin %s", [d, npa_breaking_earliest(p)])}
}

npa_violations contains v if {
	some p in npa_parcels
	object.get(npa(p), "breaking_date", null) != null
	object.get(npa(p), "used_after_breaking", false) == true
	v := {"rule_id": "O61C-NPA-005", "scope": p.parcel_id, "message": "Nutzung nach Umbruch vor dem 31. Dezember (Nutzungsverbot)"}
}

npa_violations contains v if {
	some p in npa_parcels
	npa_psm_violation(p)
	v := {"rule_id": "O61C-NPA-006", "scope": p.parcel_id, "message": "Einsatz nicht bio-konformer Pflanzenschutzmittel auf NPA"}
}

npa_violations contains v if {
	some p in npa_parcels
	npa_fertilized(p)
	v := {"rule_id": "O61C-NPA-007", "scope": p.parcel_id, "message": "Düngung auf NPA verboten"}
}

npa_violations contains v if {
	some p in npa_parcels
	m := object.get(npa(p), "removal_method", null)
	m != null
	m != "none"
	not m in allowed_removal_method_codes
	v := {"rule_id": "O61C-NPA-008", "scope": p.parcel_id, "message": sprintf("Beseitigung mit unzulässiger Methode %v (nur Häckseln oder Einarbeiten)", [m])}
}

npa_violations contains v if {
	some p in npa_parcels
	count(counted_cuts(p)) > params.npa_max_cuts_per_year
	v := {"rule_id": "O61C-NPA-009", "scope": p.parcel_id, "message": sprintf("%d Pflegeschnitte im Jahr (maximal 2)", [count(counted_cuts(p))])}
}

npa_violations contains v if {
	some p in npa_parcels
	not npa_first_year(p)
	count(all_cuts_in_year(p)) == 0
	object.get(npa(p), "maintenance_in_previous_year", true) == false
	v := {"rule_id": "O61C-NPA-010", "scope": p.parcel_id, "message": "Keine Pflegemahd bzw. kein Häckseln im laufenden und im Vorjahr (mindestens jedes zweite Jahr)"}
}

npa_violations contains v if {
	some p in npa_parcels
	some e in all_cuts_in_year(p)
	e.type == "cleaning_cut"
	not cleaning_cut_permitted(p)
	v := {"rule_id": "O61C-NPA-011", "scope": p.parcel_id, "message": sprintf("Reinigungsschnitt am %s unzulässig (nur im ersten Antragsjahr auf Neuansaatflächen)", [e.date])}
}

npa_violations contains v if {
	npa_early_cut_share_exceeded
	v := {"rule_id": "O61C-NPA-012", "scope": "farm", "message": sprintf("%.2f ha von %.2f ha NPA vor dem 1. August gemäht/gehäckselt (maximal 50 %%)", [npa_early_cut_area_ha, npa_total_area_ha])}
}

npa_violations contains v if {
	some p in npa_parcels
	some e in all_cuts_in_year(p)
	object.get(e, "biomass_removed", false) == true
	v := {"rule_id": "O61C-NPA-013", "scope": p.parcel_id, "message": sprintf("Mähgut am %s verbracht (nur Pflegemahd ohne Abtransport zulässig)", [e.date])}
}

npa_violations contains v if {
	some p in npa_parcels
	some e in all_cuts_in_year(p)
	object.get(e, "biomass_used", false) == true
	v := {"rule_id": "O61C-NPA-013", "scope": p.parcel_id, "message": sprintf("Mähgut vom %s genutzt", [e.date])}
}

npa_violations contains v if {
	some p in npa_parcels
	object.get(npa(p), "grazed", false) == true
	v := {"rule_id": "O61C-NPA-014", "scope": p.parcel_id, "message": "Beweidung von NPA nicht erlaubt"}
}

npa_violations contains v if {
	some p in npa_parcels
	some other in object.get(parcel_status(p), "other_measure_premium_codes", [])
	not combinable_on_single_area(params.measure_code, other)
	v := {"rule_id": "O61C-PREM-004", "scope": p.parcel_id, "message": sprintf("NPA ist prämienmäßig nicht mit Maßnahme %v auf der Einzelfläche kombinierbar", [other])}
}

# O61C-PREM-004: NPA ist auf keine anderen Verpflichtungen der SRL anrechenbar.
npa_creditable_to_other_obligations := false

# Teilnahme-, Antrags- und Vertragsregeln der Maßnahme 1C
# (Informationsblatt 1C Kap. 3, 6; Allgemeine Teilnahmebedingungen Kap. 5.2, 5.3, 5.9, 6;
# SRL Punkte 1.4, 1.6.1, 1.7.1.1, 1.9.4, 1.10.5, 1.12.1.1).
package oepul.o6_1c

applicant_rules := data.o6_1c.applicant_rules

measure_lists := data.o6_1c.measure_lists

# --- Angebotszeitraum -------------------------------------------------------------

# O61C-CONTRACT-001: Maßnahme ab Antragsjahr 2025 und längstens bis zum Ende der SRL-Laufzeit 2028.
default measure_offered_in_year := false

measure_offered_in_year if {
	year >= params.offered_from_year
	year <= params.programme_last_year
}

# --- Beantragung ------------------------------------------------------------------

measure_1c_participations contains p if {
	some p in participations
	p.measure_code == params.measure_code
}

# O61C-APPL-001: Beantragung im Maßnahmenantrag bis 31.12. vor Vertragsbeginn.
application_deadline_for(first_contract_year) := date_of(first_contract_year - 1, params.application_deadline_month_day)

application_in_time(p) if {
	object.get(p, "application_date", null) != null
	p.application_date <= application_deadline_for(p.first_contract_year)
}

# O61C-APPL-002: Letzter Einstieg mit Förderjahr 2027 (Beantragung bis 31.12.2026).
entry_year_allowed(p) if {
	p.first_contract_year >= params.offered_from_year
	p.first_contract_year <= params.last_contract_start_year
}

# O61C-CONTRACT-003 / O61C-GEN-APPL-003: automatische Verlängerung, Weiterführung über den Mehrfachantrag.
default mfa_submitted := false

mfa_submitted if object.get(oepul, "mfa_submitted", true) == true

# O61C-GEN-APPL-004: Abmeldung im laufenden Förderjahr -> Maßnahme im betroffenen Jahr nicht gültig.
deregistration_invalidates_year(p) if deregistered_in_year(p)

# Abmeldung in einem Vorjahr beendet die Teilnahme; Wiedereinstieg nur mit neuem Maßnahmenantrag.
deregistered_before_year(p) if {
	d := object.get(p, "deregistration_date", null)
	d != null
	d < date_in_year("01-01")
}

reentry_requires_new_application(p) if deregistered_before_year(p)

category_contract_valid(p) if {
	measure_offered_in_year
	application_in_time(p)
	entry_year_allowed(p)
	p.first_contract_year <= year
	not deregistration_invalidates_year(p)
	not deregistered_before_year(p)
	mfa_submitted
	applicant_eligible
	min_farm_size_met
	not category_blocked(p)
}

contract_valid_for_category(category) if {
	some p in measure_1c_participations
	object.get(p, "category", null) == category
	category_contract_valid(p)
}

# --- Kombinationsausschluss NPA mit UBB/BIO ---------------------------------------

# O61C-APPL-003: Betriebe in UBB (1A) oder BIO (1B, ausgenommen Teilbetrieb Wein/Obst/Hopfen)
# können nicht an der Kategorie „Nichtproduktive Ackerflächen" teilnehmen.
default ubb_or_bio_conflict := false

ubb_or_bio_conflict if participates("1A")

ubb_or_bio_conflict if {
	some p in participations
	p.measure_code == "1B"
	not deregistered_in_year(p)
