default min_farm_size_met := false

min_farm_size_met if not first_oepul_year

min_farm_size_met if {
	first_oepul_year
	min_size_area_ha >= applicant_rules.min_farm_size_first_year.agricultural_area_min_ha
}

min_farm_size_met if {
	first_oepul_year
